WITH filtered AS (SELECT *, COALESCE(age, 0) AS age_filled, COALESCE(city, 'OTHER') AS resolved_city FROM customers WHERE city IS NOT NULL AND NOT is_active) SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, age_filled, resolved_city, ROW_NUMBER() OVER (PARTITION BY city, country ORDER BY age_filled, id) AS event_seq, ROW_NUMBER() OVER (ORDER BY credit_limit DESC, id) AS row_seq, LAST_VALUE(credit_limit) IGNORE NULLS OVER (PARTITION BY city ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_credit_limit, FIRST_VALUE(city) IGNORE NULLS OVER (PARTITION BY country, segment ORDER BY age_filled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_city, ROUND(age / SUM(age) OVER (PARTITION BY segment), 4) AS age_share FROM filtered
